def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]

    directions = [
        (lambda r, c: r, h),
        (lambda r, c: c, w),
        (lambda r, c: r + c, h + w - 1),
        (lambda r, c: r - c, h + w - 1),
    ]

    best = None
    best_score = float("-inf")
    for key_fn, span in directions:
        groups = {}
        for r, c, color in points:
            groups.setdefault(key_fn(r, c), []).append(color)

        score = 0
        for colors in groups.values():
            counts = {}
            for color in colors:
                counts[color] = counts.get(color, 0) + 1
            total = len(colors)
            same = sum(n * (n - 1) // 2 for n in counts.values())
            mixed = total * (total - 1) // 2 - same
            score += same - mixed

        if score > best_score:
            best_score = score
            best = (key_fn, span)

    key_fn, span = best
    clues = {}
    for r, c, color in points:
        k = key_fn(r, c)
        if k in clues and clues[k] != color:
            continue
        clues[k] = color

    # Find the shortest repeating stripe pattern consistent with the clues.
    period = span
    motif = {}
    for p in range(1, span + 1):
        trial = {}
        valid = True
        for k, color in clues.items():
            residue = k % p
            if residue in trial and trial[residue] != color:
                valid = False
                break
            trial[residue] = color
        if valid:
            period, motif = p, trial
            break

    known = list(motif)
    if not known:
        return [[0] * w for _ in range(h)]

    def stripe_color(k):
        residue = k % period
        if residue in motif:
            return motif[residue]
        nearest = min(
            known,
            key=lambda x: min((residue - x) % period, (x - residue) % period)
        )
        return motif[nearest]

    return [[stripe_color(key_fn(r, c)) for c in range(w)] for r in range(h)]
